 public const string Work="D:/游戏设计/Codex工作区/work/2026-10-06-AudioPass0/runtime/";
 [Serializable] public class Step {public string label,kind="wait",keys="",target="",text="",flag="";public float seconds=1,x,y;public bool run,mouse,pointer,capture;public int slot=1;}
