 static AudioPass0Replay instance;
 readonly Queue<Step> queue=new Queue<Step>();readonly HashSet<KeyCode> held=new HashSet<KeyCode>(),prior=new HashSet<KeyCode>();
 readonly Dictionary<GameSaveService,FourSlotSaveStore> original=new Dictionary<GameSaveService,FourSlotSaveStore>();
 P01ReplayDriver driver;Step active;float elapsed,nextRead,nextStatus,noDialogue;bool mouse,oldMouse;Vector3 pointer;string error="";int serial;GuitarRhythmGame rhythmObserved;int rhythmId=-1;readonly HashSet<int> rhythmFired=new HashSet<int>();ChildhoodDragHandle dragHandle;Vector2 dragFrom,dragTo;
 public static void Begin(){if(!EditorApplication.isPlaying)throw new Exception("Play mode required");if(instance!=null)return;Directory.CreateDirectory(Work);instance=new AudioPass0Replay();var go=new GameObject("AudioPass0 opt-in isolated QA");UnityEngine.Object.DontDestroyOnLoad(go);instance.driver=go.AddComponent<P01ReplayDriver>();instance.driver.Tick=instance.Update;instance.driver.Cleanup=instance.Cleanup;instance.BindStore();GameplayInput.Replay=instance;Application.logMessageReceived+=instance.OnLog;GamePause.Instance?.ShowMainMenu();instance.Log("BEGIN fresh isolated slots, original gameplay inputs and focus pause retained");instance.Report();}
 public static void Snapshot(){instance?.Report();}
 public static void End(){if(instance!=null)UnityEngine.Object.Destroy(instance.driver.gameObject);}
 void BindStore(){var rt=PersistentRuntime.Instance;if(!rt)return;var service=rt.GetComponent<GameSaveService>();if(!service||original.ContainsKey(service))return;original[service]=service.Store;typeof(GameSaveService).GetProperty("Store").GetSetMethod(true).Invoke(service,new object[]{new FourSlotSaveStore(Work+"isolated-slots")});Log("ISOLATED runtime "+rt.name);}
 void Cleanup(){P08ReviewRecorder.Stop();foreach(var pair in original)if(pair.Key)typeof(GameSaveService).GetProperty("Store").GetSetMethod(true).Invoke(pair.Key,new object[]{pair.Value});if(ReferenceEquals(GameplayInput.Replay,this))GameplayInput.Replay=null;Application.logMessageReceived-=OnLog;instance=null;Log("END QA detached");}
 void OnLog(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)File.AppendAllText(Work+"runtime-errors.txt",DateTime.Now.ToString("O")+" "+message+"\n"+stack+"\n");}
 public bool Key(KeyCode key)=>held.Contains(key);public bool KeyDown(KeyCode key)=>held.Contains(key)&&!prior.Contains(key);
 public float Axis(string axis)=>axis=="Horizontal"?((Key(KeyCode.D)||Key(KeyCode.RightArrow)?1:0)-(Key(KeyCode.A)||Key(KeyCode.LeftArrow)?1:0)):axis=="Vertical"?((Key(KeyCode.W)||Key(KeyCode.UpArrow)?1:0)-(Key(KeyCode.S)||Key(KeyCode.DownArrow)?1:0)):0;
 public bool Mouse(int b)=>b==0&&mouse;public bool MouseDown(int b)=>b==0&&mouse&&!oldMouse;public bool MouseUp(int b)=>b==0&&!mouse&&oldMouse;public Vector3 Pointer=>pointer;
 void Update(){BindStore();GameplayInput.Replay=this;prior.Clear();prior.UnionWith(held);oldMouse=mouse;float now=Time.realtimeSinceStartup;
  if(now>nextRead){nextRead=now+.12f;var path=Work+"queue.json";if(File.Exists(path)){try{var batch=JsonUtility.FromJson<Batch>(File.ReadAllText(path));File.Delete(path);foreach(var step in batch.steps)queue.Enqueue(step);error="";}catch(Exception e){error=e.Message;Log("QUEUE ERROR "+e);}}}
  held.Clear();mouse=false;
  var acquisitionNow=PersistentRuntime.Instance?PersistentRuntime.Instance.GetComponent<P07AcquisitionPresentation>():null;
  if(active!=null&&active.kind!="dialogue"&&active.kind!="checkpoint"&&active.kind!="record"&&active.kind!="stoprecord"&&!(active.kind=="key"&&active.keys.Contains("Escape"))&&acquisitionNow&&acquisitionNow.IsOpen&&Application.isFocused){if(now%.7f<.11f)held.Add(KeyCode.Escape);if(now>nextStatus){nextStatus=now+.5f;Report();}return;}
  if(active==null&&queue.Count>0){active=queue.Dequeue();elapsed=-Time.unscaledDeltaTime;noDialogue=0;Log("START "+JsonUtility.ToJson(active));}
  if(active!=null&&Application.isFocused){bool allowPause=(active.kind=="dialogue"&&PersistentRuntime.Instance&&PersistentRuntime.Instance.GetComponent<P07AcquisitionPresentation>()?.IsOpen==true)||(active.kind=="key"&&active.keys.Contains("Escape"))||active.kind=="load"||active.kind=="importnatural"||active.kind=="button"||active.kind=="checkpoint"||active.kind=="record"||active.kind=="stoprecord";if(!GamePause.IsPaused||allowPause){elapsed+=Time.unscaledDeltaTime;try{if(TickStep(active))Finish();else if(elapsed>Mathf.Max(.05f,active.seconds)){if(active.kind=="wait"||active.kind=="key")Finish();else throw new Exception("Timed out "+active.kind+" "+active.target);}}catch(Exception e){error=e.ToString();Log("FAIL "+active.label+" "+error);active=null;queue.Clear();held.Clear();mouse=false;Report();}}}
  if(now>nextStatus){nextStatus=now+.5f;Report();}
 }
 bool TickStep(Step s){var rt=PersistentRuntime.Instance;var player=rt?rt.GetComponent<GameControlManager>()?.ActivePlayer:null;
  switch(s.kind){
   case "wait":return elapsed>=s.seconds;
   case "key":foreach(var key in s.keys.Split(new[]{',',' '},StringSplitOptions.RemoveEmptyEntries))held.Add((KeyCode)Enum.Parse(typeof(KeyCode),key));mouse=s.mouse;if(s.pointer)pointer=new Vector3(s.x,s.y);return elapsed>=s.seconds;
   case "walk":case "goto":if(!player)return false;var chosen=player.GetComponent<PlayerInteraction>()?.CurrentVisualTarget as Component;if(s.kind=="walk"&&chosen&&Match(chosen.transform,s.target))return true;float dest=s.x;if(s.kind=="walk"){var candidates=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Exclude).Where(m=>m is IInteractable&&Match(m.transform,s.target)).ToArray();if(candidates.Length!=1)throw new Exception("Expected unique active hotspot: "+s.target+" found="+candidates.Length);dest=candidates[0].transform.position.x;}float dx=dest-player.transform.position.x;if(Mathf.Abs(dx)<.065f)return true;held.Add(dx>0?KeyCode.D:KeyCode.A);if(s.run)held.Add(KeyCode.LeftShift);return false;
   case "goto2d":if(!player)return false;Vector2 delta=new Vector2(s.x,s.y)-(Vector2)player.transform.position;if(delta.magnitude<.10f)return true;if(Mathf.Abs(delta.x)>.065f)held.Add(delta.x>0?KeyCode.D:KeyCode.A);if(Mathf.Abs(delta.y)>.065f)held.Add(delta.y>0?KeyCode.W:KeyCode.S);if(s.run)held.Add(KeyCode.LeftShift);return false;
   case "rhythm":var game=UnityEngine.Object.FindAnyObjectByType<GuitarRhythmGame>();if(!game||!game.IsRunning)return game&&game.Completed;if(rhythmObserved!=game){rhythmObserved=game;game.Judged+=(k,ok,t,why)=>Log("RHYTHM "+game.PhraseIndex+" "+k+" success="+ok+" t="+t.ToString("F3")+" "+why);rhythmId=-1;}if(game.WaitingForStart){if(elapsed%.5f<.12f)held.Add(KeyCode.E);return false;}if((bool)typeof(GuitarRhythmGame).GetField("transitioning",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(game))return false;int identity=game.PhraseIndex*10000+game.RetryCount;if(identity!=rhythmId){rhythmId=identity;rhythmFired.Clear();}var phrase=game.phrases[game.PhraseIndex];held.Add(phrase.heldChord);for(int n=0;n<phrase.notes.Length;n++)if(!rhythmFired.Contains(n)&&game.PhraseTime>=phrase.notes[n].time-.015f){held.Add(phrase.notes[n].key);rhythmFired.Add(n);Log("INPUT rhythm "+game.PhraseIndex+" "+phrase.notes[n].key+" time="+game.PhraseTime.ToString("F3"));break;}return false;
   case "slider":var slide=UnityEngine.Object.FindObjectsByType<Slider>(FindObjectsInactive.Exclude).Where(v=>v.isActiveAndEnabled&&Match(v.transform,s.target)).ToArray();if(slide.Length!=1)return false;slide[0].value=s.x;Log("UI slider "+s.target+" value="+s.x);return true;
   case "dropdown":var drops=UnityEngine.Object.FindObjectsByType<TMP_Dropdown>(FindObjectsInactive.Exclude).Where(v=>v.isActiveAndEnabled&&Match(v.transform,s.target)).ToArray();if(drops.Length!=1)return false;drops[0].value=s.slot;return true;
   case "dragstory":if(dragHandle==null){dragHandle=UnityEngine.Object.FindObjectsByType<ChildhoodDragHandle>(FindObjectsInactive.Exclude).Single(h=>!h.ring&&h.cardIndex==s.slot);var dr=(RectTransform)dragHandle.transform;dragFrom=RectTransformUtility.WorldToScreenPoint(null,dr.TransformPoint(dr.rect.center));var sr=dragHandle.owner.StorySlot;dragTo=RectTransformUtility.WorldToScreenPoint(null,sr.TransformPoint(sr.rect.center));var startEvent=new PointerEventData(EventSystem.current){position=dragFrom,pressPosition=dragFrom,button=PointerEventData.InputButton.Left};dragHandle.OnPointerDown(startEvent);dragHandle.OnBeginDrag(startEvent);Log("UI pointer drag start card="+s.slot);}var dragEvent=new PointerEventData(EventSystem.current){position=Vector2.Lerp(dragFrom,dragTo,Mathf.Clamp01(elapsed/.6f)),pressPosition=dragFrom,button=PointerEventData.InputButton.Left};dragHandle.OnDrag(dragEvent);if(elapsed>=.6f){dragHandle.OnEndDrag(dragEvent);dragHandle=null;return true;}return false;
   case "throw":var ballGame=UnityEngine.Object.FindAnyObjectByType<BasketballThrowController>();if(!ballGame)return false;if(ballGame.State!=BasketballThrowController.ThrowState.Aiming)return elapsed>=.60f;var ballBody=(Rigidbody2D)typeof(BasketballThrowController).GetField("ball",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(ballGame);Vector3 screen=Camera.main.WorldToScreenPoint(ballBody.position);float perPixel=(float)typeof(BasketballThrowController).GetField("speedPerReferencePixel",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(ballGame);Vector2 pull=new Vector2(s.x,s.y)*(Screen.height/900f)/perPixel;pointer=screen-(Vector3)(pull*Mathf.Clamp01((elapsed-.12f)/.4f));mouse=elapsed<.60f;return elapsed>=.62f;
   case "wheel":var wheels=UnityEngine.Object.FindObjectsByType<FourDigitLock>(FindObjectsInactive.Exclude).Where(w=>Match(w.transform,s.target)).ToArray();if(wheels.Length!=1)return false;if(wheels[0].Value==s.slot)return true;if(prior.Count==0&&elapsed%.14f<.04f)wheels[0].OnScroll(new PointerEventData(EventSystem.current){scrollDelta=Vector2.up});return false;
   case "rub":var pencil=UnityEngine.Object.FindAnyObjectByType<PencilDeskCloseup>();if(!pencil)return false;if(!pencil.IsOpen||pencil.IsPlayingGrab)return true;if(!pencil.CanRub)return false;var surface=(RectTransform)typeof(PencilDeskCloseup).GetField("writingSurface",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(pencil);float u=elapsed/.55f;int row=Mathf.FloorToInt(u);float fract=u-row;float localX=Mathf.Lerp(-surface.rect.width*.48f,surface.rect.width*.48f,row%2==0?fract:1-fract);float localY=-surface.rect.height*.46f+row*18f;pointer=RectTransformUtility.WorldToScreenPoint(null,surface.TransformPoint(new Vector2(localX,localY)));mouse=true;return false;
   case "untilDialogue":if(!player)return false;if(UnityEngine.Object.FindAnyObjectByType<DialogueManager>()?.IsDialogueActive()==true)return true;held.Add(s.x>=0?KeyCode.D:KeyCode.A);if(s.run)held.Add(KeyCode.LeftShift);return false;
   case "dialogue":var d=UnityEngine.Object.FindAnyObjectByType<DialogueManager>();bool open=d&&d.IsDialogueActive();var acquisition=rt?rt.GetComponent<P07AcquisitionPresentation>():null;if(acquisition&&acquisition.IsOpen){if(elapsed%.7f<.11f)held.Add(KeyCode.Escape);noDialogue=0;return false;}var puddleContinue=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsInactive.Exclude).Any(b=>b.isActiveAndEnabled&&b.name=="PuddleContinue");if(open||puddleContinue||UnityEngine.Object.FindObjectsByType<DemoComicSequence>(FindObjectsInactive.Exclude).Any(v=>v.IsOpen)){if(elapsed%.65f<.12f)held.Add(KeyCode.E);noDialogue=0;}else noDialogue+=Time.unscaledDeltaTime;return elapsed>2.7f&&noDialogue>1.8f&&(!rt||(!rt.GetComponent<GameControlManager>().IsLockedBy(ControlLockReason.Interaction)&&!rt.GetComponent<GameControlManager>().IsLockedBy(ControlLockReason.Dialogue)));
   case "waitfree":return rt&&!rt.GetComponent<GameControlManager>().IsLocked()&&!rt.GetComponent<GameSaveService>().IsRestoring;
   case "waitflag":return rt&&rt.GetComponent<StoryStateManager>().Has((StoryFlag)Enum.Parse(typeof(StoryFlag),s.flag));
   case "button":var buttons=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsInactive.Exclude).Where(b=>b.isActiveAndEnabled&&b.interactable&&(Match(b.transform,s.target)||b.GetComponentInChildren<TMP_Text>()?.text==s.target)).ToArray();if(buttons.Length==0)return false;if(buttons.Length!=1)throw new Exception("Ambiguous button "+s.target);Log("UI original onClick "+PathOf(buttons[0].transform));buttons[0].onClick.Invoke();return true;
   case "text":var fields=UnityEngine.Object.FindObjectsByType<TMP_InputField>(FindObjectsInactive.Exclude).Where(f=>f.isActiveAndEnabled&&f.interactable).ToArray();if(fields.Length!=1)return false;fields[0].text=s.text;Log("UI original input text "+PathOf(fields[0].transform));return true;
   case "checkpoint":if(s.capture){P07EvidenceRecorder.ReserveStillFrame();ScreenCapture.CaptureScreenshot(Work+(++serial).ToString("D3")+"_"+s.label+".png");}if(rt&&rt.GetComponent<GameSaveService>().CanSave(out _))File.WriteAllText(Work+s.label+"_natural_snapshot.json",JsonUtility.ToJson(rt.GetComponent<GameSaveService>().Capture(s.slot),true));Report(s.label+"_status.json");return true;
   case "save":if(!rt.GetComponent<GameSaveService>().Save(s.slot,true,out var why))throw new Exception(why);return true;
   case "load":if(!rt.GetComponent<GameSaveService>().Load(s.slot,out var why2))throw new Exception(why2);return true;
   case "importnatural":string sourcePath=Path.GetFullPath(Path.Combine(Work,s.target));if(!sourcePath.StartsWith(Path.GetFullPath(Work),StringComparison.OrdinalIgnoreCase)||!s.target.EndsWith("_natural_snapshot.json"))throw new Exception("Only actual AudioPass0 natural snapshot source allowed");var natural=JsonUtility.FromJson<GameSaveData>(File.ReadAllText(sourcePath));if(natural.slot!=s.slot)throw new Exception("Preserve original snapshot slot");rt.GetComponent<GameSaveService>().Store.Write(s.slot,natural,true);Log("LOAD ORIGINAL NATURAL CHECKPOINT "+sourcePath+" (no payload fields assigned)");if(!rt.GetComponent<GameSaveService>().Load(s.slot,out var naturalWhy))throw new Exception(naturalWhy);return true;
   case "record":P08ReviewRecorder.Begin(driver,Work+s.label+".mp4",s.seconds);return true;
   case "stoprecord":P08ReviewRecorder.Stop();return true;
   default:throw new Exception("Unknown step kind "+s.kind);
  }
 }
 void Finish(){dragHandle=null;Log("PASS "+active.label+" "+SceneManager.GetActiveScene().name+" dt="+elapsed.ToString("F2"));active=null;}
 static bool Match(Transform t,string value)=>t.name==value||PathOf(t)==value;
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 void Log(string value)=>File.AppendAllText(Work+"events.txt",DateTime.Now.ToString("O")+" "+value+"\n");
 void Report(string filename="status.json"){var s=new State{stamp=DateTime.Now.ToString("O"),scene=SceneManager.GetActiveScene().name,time=Time.realtimeSinceStartup,active=active?.label??"idle",stepTime=elapsed,queued=queue.Count,focused=Application.isFocused,paused=GamePause.IsPaused,width=Screen.width,height=Screen.height,error=error};var rt=PersistentRuntime.Instance;if(rt){var c=rt.GetComponent<GameControlManager>();var p=c.ActivePlayer;s.locked=c.IsLocked();s.canSave=rt.GetComponent<GameSaveService>().CanSave(out s.saveReason);s.opening=rt.GetComponent<P07Interface>()?.OpeningPhase;var story=rt.GetComponent<StoryStateManager>();s.flags=Enum.GetValues(typeof(StoryFlag)).Cast<StoryFlag>().Where(story.Has).Select(x=>x.ToString()).ToArray();if(p){s.player=p.transform.position;var target=p.GetComponent<PlayerInteraction>()?.CurrentVisualTarget as Component;s.target=target?PathOf(target.transform):"";}}var cam=Camera.main;if(cam){s.camera=cam.transform.position;s.cameraSize=cam.orthographicSize;}var d=UnityEngine.Object.FindAnyObjectByType<DialogueManager>();if(d&&d.IsDialogueActive()){var flags=BindingFlags.Instance|BindingFlags.NonPublic;s.dialogue="index="+typeof(DialogueManager).GetField("currentLineIndex",flags)?.GetValue(d)+" asset="+typeof(DialogueManager).GetField("currentDialogue",flags)?.GetValue(d);}
  var maze=UnityEngine.Object.FindAnyObjectByType<Scene03MazeController>();if(maze&&maze.mazeSpace){s.inMaze=maze.IsInMaze;s.mazeOrigin=maze.mazeSpace.position;s.mazeCellSize=maze.cellSize;s.mazeLayout=maze.CurrentLayout;var cell=maze.CellAt(s.player);s.mazeRow=cell.x;s.mazeColumn=cell.y;}var guitar=UnityEngine.Object.FindAnyObjectByType<GuitarRhythmGame>();if(guitar){s.rhythmRunning=guitar.IsRunning;s.rhythmTime=guitar.PhraseTime;s.rhythmPhrase=guitar.PhraseIndex;s.rhythmRetries=guitar.RetryCount;}var basketball=UnityEngine.Object.FindAnyObjectByType<BasketballThrowController>();if(basketball){s.basketball=basketball.State.ToString();var bf=BindingFlags.Instance|BindingFlags.NonPublic;var bb=(Rigidbody2D)typeof(BasketballThrowController).GetField("ball",bf).GetValue(basketball);var board=(Collider2D)typeof(BasketballThrowController).GetField("backboard",bf).GetValue(basketball);if(bb){s.ballWorld=bb.position;s.ballScreen=Camera.main.WorldToScreenPoint(bb.position);}if(board)s.boardWorld=board.bounds.center;}s.drags=UnityEngine.Object.FindObjectsByType<ChildhoodDragHandle>(FindObjectsInactive.Exclude).Select(h=>{var rect=(RectTransform)h.transform;return new UI{path=PathOf(h.transform),text=h.ring?"ring":h.cardIndex.ToString(),screen=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center))};}).ToArray();s.sliders=UnityEngine.Object.FindObjectsByType<Slider>(FindObjectsInactive.Exclude).Select(h=>{var rect=(RectTransform)h.transform;return new UI{path=PathOf(h.transform),screen=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center)),value=h.value,min=h.minValue,max=h.maxValue};}).ToArray();
  var layout=UnityEngine.Object.FindAnyObjectByType<SchoolLayoutController>();if(layout){s.room=layout.CurrentRoom;s.world=layout.Variant.ToString();s.actor=layout.Actor.ToString();}var chase=UnityEngine.Object.FindAnyObjectByType<SchoolChaseController>();if(chase){s.chase=chase.Step.ToString();s.route=chase.Route.ToString();s.enemy=chase.EnemyPosition;}var fog=UnityEngine.Object.FindAnyObjectByType<FogIntroController>();if(fog)s.fog=fog.Phase.ToString();var lamp=rt?rt.GetComponent<OilLampController>():null;if(lamp)s.charge=lamp.Charge01;var ending=UnityEngine.Object.FindAnyObjectByType<EndingDirector>();if(ending)s.ending=ending.Step.ToString();var pencil=UnityEngine.Object.FindAnyObjectByType<PencilDeskCloseup>();if(pencil){s.rubOpen=pencil.IsOpen;s.coverage1=pencil.FirstCharacterCoverage;s.coverage2=pencil.SecondCharacterCoverage;}s.comic=UnityEngine.Object.FindObjectsByType<DemoComicSequence>(FindObjectsInactive.Exclude).Any(v=>v.IsOpen);if(rt)s.locks=Enum.GetValues(typeof(ControlLockReason)).Cast<ControlLockReason>().Where(rt.GetComponent<GameControlManager>().IsLockedBy).Select(v=>v.ToString()).ToArray();s.digits=UnityEngine.Object.FindObjectsByType<FourDigitLock>(FindObjectsInactive.Exclude).Select(w=>{var rect=(RectTransform)w.transform;return new UI{path=PathOf(w.transform),value=w.Value,screen=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center))};}).ToArray();
  s.runtimes=UnityEngine.Object.FindObjectsByType<PersistentRuntime>(FindObjectsInactive.Exclude).Length;s.players=UnityEngine.Object.FindObjectsByType<PlayerController>(FindObjectsInactive.Exclude).Length;s.cameras=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Exclude).Count(x=>x.CompareTag("MainCamera"));
  s.texts=UnityEngine.Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Exclude).Where(t=>t.isActiveAndEnabled&&!string.IsNullOrWhiteSpace(t.text)).Select(t=>t.text).ToArray();s.hotspots=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Exclude).Where(m=>m is IInteractable).Select(m=>new Hot{path=PathOf(m.transform),type=m.GetType().Name,position=m.transform.position,prompt=((IInteractable)m).GetInteractionPrompt()}).ToArray();s.buttons=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsInactive.Exclude).Where(b=>b.isActiveAndEnabled&&b.interactable).Select(b=>{var rect=b.transform as RectTransform;var cv=b.GetComponentInParent<Canvas>();return new UI{path=PathOf(b.transform),text=b.GetComponentInChildren<TMP_Text>()?.text,screen=RectTransformUtility.WorldToScreenPoint(cv&&cv.renderMode!=RenderMode.ScreenSpaceOverlay?cv.worldCamera:null,rect.TransformPoint(rect.rect.center))};}).ToArray();File.WriteAllText(Work+filename,JsonUtility.ToJson(s,true));
 }
